def compute(vars):
    doubtful_receivables = -vars["v1"]
    trade_receivables = vars["v2"]
    if trade_receivables == 0:
        return None
    percentage = doubtful_receivables / trade_receivables * 100
    return {
        "value": percentage,
        "trace": {
            "doubtful_receivables": doubtful_receivables,
            "trade_receivables": trade_receivables,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
